<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$pdo=db();
$stats=$pdo->query("SELECT COUNT(*) resumes,SUM(stage NOT IN ('Rejected')) active,SUM(score>=70) qualified,SUM(stage='Interview') interviews,SUM(stage='Offer') offers,SUM(country_code IS NULL OR country_code='') missing_country FROM candidates")->fetch();
$jobs=$pdo->query("SELECT j.id,j.title,j.description,j.created_at,COUNT(c.id) resumes,COALESCE(ROUND(AVG(c.score)),0) avg_score FROM jobs j LEFT JOIN candidates c ON c.role_title=j.title GROUP BY j.id ORDER BY j.created_at DESC LIMIT 6")->fetchAll();
$profiles=$pdo->query("SELECT wp.id,wp.name,COUNT(wi.id) resumes,SUM(wi.disposition='wishlist') active,SUM(wi.disposition='selected') selected FROM wishlist_profiles wp LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id GROUP BY wp.id ORDER BY wp.created_at DESC LIMIT 6")->fetchAll();
$countries=$pdo->query("SELECT country_code,country_name,COUNT(*) total FROM candidates WHERE COALESCE(country_code,country_name,'')<>'' GROUP BY country_code,country_name ORDER BY total DESC LIMIT 12")->fetchAll();foreach($countries as &$country)$country['country_code']=countryCodeFromName($country['country_code'],$country['country_name']);unset($country);
$sources=$pdo->query("SELECT source_name,COUNT(*) total FROM candidates GROUP BY source_name ORDER BY total DESC LIMIT 6")->fetchAll();$countryTotals=array_map(fn($x)=>(int)$x['total'],$countries);$maxCountry=$countryTotals?max($countryTotals):1;
$stageRows=$pdo->query("SELECT stage,COUNT(*) total FROM candidates GROUP BY stage")->fetchAll();$stageMap=[];foreach($stageRows as $row)$stageMap[$row['stage']]=(int)$row['total'];
$activePage='dashboard';$pageTitle='Dashboard · ResumeIQ';$pageStyles='<style>.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{padding:17px;display:flex;align-items:center;gap:13px}.metric-icon{width:43px;height:43px;border-radius:10px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-size:16px}.metric:nth-child(2) .metric-icon{background:#edf5ff;color:#347ce1}.metric:nth-child(3) .metric-icon{background:var(--green-soft);color:var(--green)}.metric:nth-child(4) .metric-icon{background:var(--amber-soft);color:var(--amber)}.metric strong{display:block;font-size:23px;letter-spacing:-.04em}.metric span{font-size:9px;color:var(--muted)}.dash-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:10px;margin-top:10px}.dash-panel{padding:18px}.dash-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.dash-title h2{font-size:14px;margin:0}.profile-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.profile-card{padding:16px;border:1px solid #e8e5f4;border-radius:11px;background:#f1edff;min-height:150px;display:flex;flex-direction:column}.profile-card:nth-child(3n+2){background:#eaf6ff}.profile-card:nth-child(3n){background:#fff3e8}.profile-card h3{font-size:16px;margin:20px 0 6px}.profile-card p{font-size:9px;line-height:1.55;color:#6f7280;margin:0}.profile-foot{margin-top:auto;display:flex;justify-content:space-between;font-size:9px;color:var(--muted)}.role-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:9px}.role{border:1px solid var(--line);border-radius:11px;overflow:hidden}.role-cover{height:70px;background:linear-gradient(110deg,#597cff,#a478ff,#f5a4bc)}.role:nth-child(2) .role-cover{background:linear-gradient(110deg,#5c83e9,#8edbff)}.role:nth-child(3) .role-cover{background:linear-gradient(110deg,#824fff,#e5b0df)}.role-body{padding:13px}.role-body h3{font-size:13px;margin:0 0 6px}.role-body p{font-size:9px;color:var(--muted);line-height:1.5;min-height:40px}.world{position:relative;background:#f8f9fc;border:1px solid var(--line);border-radius:10px;padding:12px;min-height:230px;overflow:hidden}.world svg{width:100%;height:145px}.land{fill:#e3defa;stroke:#fff;stroke-width:2}.country-list{display:grid;gap:6px;margin-top:8px}.country{display:grid;grid-template-columns:80px 1fr 28px;gap:7px;align-items:center;font-size:9px}.bar{height:6px;background:#efeff5;border-radius:3px;overflow:hidden}.bar i{display:block;height:100%;background:var(--primary);border-radius:3px}.source-list{display:grid;gap:8px}.source-row{display:flex;justify-content:space-between;font-size:10px;padding-bottom:7px;border-bottom:1px solid var(--line)}.funnel{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.funnel div{padding:9px 5px;text-align:center;background:#f8f7fd;border:1px solid var(--line);border-radius:7px}.funnel strong{display:block;font-size:14px}.funnel span{font-size:8px;color:var(--muted)}.quality{margin-top:10px;padding:10px;border-radius:8px;background:var(--amber-soft);color:#9a6a0e;font-size:9px}@media(max-width:1050px){.metric-grid{grid-template-columns:repeat(2,1fr)}.dash-grid{grid-template-columns:1fr}}@media(max-width:700px){.profile-cards,.role-cards{grid-template-columns:1fr}.metric-grid{grid-template-columns:1fr}.funnel{grid-template-columns:repeat(2,1fr)}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="metric-grid"><article class="panel metric"><span class="metric-icon"><i class="fa-regular fa-file-lines"></i></span><div><strong><?=(int)$stats['resumes']?></strong><span>Total resumes</span></div></article><article class="panel metric"><span class="metric-icon"><i class="fa-solid fa-briefcase"></i></span><div><strong><?=count($jobs)?></strong><span>Active jobs</span></div></article><article class="panel metric"><span class="metric-icon"><i class="fa-solid fa-user-check"></i></span><div><strong><?=(int)$stats['qualified']?></strong><span>Qualified · score 70%+</span></div></article><article class="panel metric"><span class="metric-icon"><i class="fa-solid fa-ranking-star"></i></span><div><strong><?=(int)$stats['interviews']?> + <?=(int)$stats['offers']?></strong><span>Interview + offer</span></div></article></section>
<section class="dash-grid"><div><article class="panel dash-panel"><div class="dash-title"><h2><i class="fa-solid fa-folder-tree" style="color:var(--primary)"></i> Job profile workflows</h2><a class="btn" href="wishlist.php">Manage profiles</a></div><div class="profile-cards"><?php foreach($profiles as $p):?><a class="profile-card" href="wishlist.php?profile=<?=$p['id']?>"><h3><?=htmlspecialchars($p['name'])?></h3><p>Curated candidates for this role profile, with selection and email workflow.</p><div class="profile-foot"><span><?=(int)$p['active']?> active</span><b><?=(int)$p['resumes']?> resumes</b></div></a><?php endforeach?><?php if(!$profiles):?><div class="empty" style="grid-column:1/-1">No profile folders yet. Create one from Wishlist.</div><?php endif?></div><div class="dash-title" style="margin-top:20px"><h2>Active role boards</h2><a href="pipeline.php">Open pipeline</a></div><div class="role-cards"><?php foreach($jobs as $j):?><article class="role"><div class="role-cover"></div><div class="role-body"><h3><?=htmlspecialchars($j['title'])?></h3><p><?=htmlspecialchars(mb_strimwidth($j['description'],0,100,'…'))?></p><div class="profile-foot"><span><?=(int)$j['resumes']?> resumes</span><b><?=(int)$j['avg_score']?>% fit</b></div></div></article><?php endforeach?><?php if(!$jobs):?><div class="empty" style="grid-column:1/-1">No jobs yet. Job creation and website sync will populate this area.</div><?php endif?></div></article><article class="panel dash-panel" style="margin-top:10px"><div class="dash-title"><h2>Hiring funnel</h2><a href="pipeline.php">View board</a></div><div class="funnel"><?php foreach(['Applied','Screening','Interview','Offer','Rejected'] as $stage):?><div><strong><?=$stageMap[$stage]??0?></strong><span><?=$stage?></span></div><?php endforeach?></div></article></div>
