<style>.world>svg{display:none}.world-map{height:155px;width:100%;display:block}.world-map path{fill:#e3defa;stroke:#fff;stroke-width:.35;transition:.15s}.world-map path.has-data{fill:var(--primary);cursor:pointer}.world-map path.has-data:hover{fill:#3f2cc4}.metric{cursor:pointer;transition:.15s}.metric:hover{transform:translateY(-2px);border-color:#d9d1ff}</style><script>const metricLinks=['candidates.php','pipeline.php','candidates.php?min=70','candidates.php?stage=Interview'];document.querySelectorAll('.metric').forEach((m,i)=>{m.tabIndex=0;m.onclick=()=>location.href=metricLinks[i];m.onkeydown=e=>{if(e.key==='Enter')m.click()}});document.querySelectorAll('.profile-card').forEach(card=>{const id=new URL(card.href).searchParams.get('profile');card.href='job_profile.php?id='+id});const countryData=<?=json_encode(array_column($countries,null,'country_code'),JSON_HEX_TAG|JSON_HEX_AMP)?>;fetch('assets/world.svg').then(r=>r.text()).then(text=>{const doc=new DOMParser().parseFromString(text,'image/svg+xml'),svg=doc.documentElement;svg.classList.add('world-map');Object.entries(countryData).forEach(([code,data])=>{const path=svg.querySelector('#'+CSS.escape(code));if(!path)return;path.classList.add('has-data');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=(data.country_name||code)+': '+data.total+' resumes';path.appendChild(title);path.addEventListener('click',()=>location.href='candidates.php?country='+encodeURIComponent(code))});document.querySelector('.world').prepend(document.importNode(svg,true))}).catch(()=>{});</script>
